package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string
var WsFirstFlag string
var WsPrevBranch string
var WsPrevAcct string
var WsBal decimal.Decimal
var WsBranchTot decimal.Decimal
var WsGrandTot decimal.Decimal
var WsSkipped int64
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var ledgerRec LedgerRec

var ledgerLines []string
var ledgerIdx int

// helpers for picture formatting

func pow10Decimal(n int) decimal.Decimal {
	p := decimal.NewFromInt(1)
	ten := decimal.NewFromInt(10)
	for i := 0; i < n; i++ {
		p = p.Mul(ten)
	}
	return p
}

func formatUnsignedAbs(abs decimal.Decimal, pic string) string {
	// pic is unsigned, contains '.' 
	dot := strings.Index(pic, ".")
	var intPic, fracPic string
	if dot >= 0 {
		intPic = pic[:dot]
		fracPic = pic[dot+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	// count digit placeholders before dot
	capBefore := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			capBefore++
		}
	}
	// integer part truncated to capBefore
	intPartDec := abs.Truncate(0)
	// cap may be up to 9, fits int64
	var intModDec decimal.Decimal
	if capBefore > 0 {
		intModDec = intPartDec.Mod(pow10Decimal(capBefore))
	} else {
		intModDec = decimal.NewFromInt(0)
	}
	intModInt := intModDec.IntPart()
	if intModInt < 0 {
		intModInt = -intModInt
	}
	digitsPad := fmt.Sprintf("%0*d", capBefore, intModInt)

	fracLen := len(fracPic)
	fracStr := ""
	if fracLen > 0 {
		fracDec := abs.Sub(intPartDec)
		powScale := pow10Decimal(fracLen)
		fracScaled := fracDec.Mul(powScale).Truncate(0)
		fracInt := fracScaled.IntPart()
		if fracInt < 0 {
			fracInt = -fracInt
		}
		fracStr = fmt.Sprintf("%0*d", fracLen, fracInt)
	}

	// first non-zero in digitsPad
	firstNonZero := capBefore // all zero
	for i := 0; i < capBefore; i++ {
		if digitsPad[i] != '0' {
			firstNonZero = i
			break
		}
	}

	// build output for intPic
	outInt := make([]rune, len(intPic))
	placeholderIdx := 0
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			digit := rune(digitsPad[placeholderIdx])
			if ch == 'Z' && placeholderIdx < firstNonZero {
				// suppressed, but check case where all zero: Z's before last should be space, last '9' is zero
				// firstNonZero == capBefore means all zero, so all Z -> space
				outInt[i] = ' '
			} else {
				outInt[i] = digit
			}
			placeholderIdx++
		} else if ch == ',' {
			outInt[i] = ','
		} else {
			outInt[i] = ch
		}
	}
	// comma suppression: if all placeholders to left are spaces -> comma becomes space
	for i, ch := range intPic {
		if ch == ',' {
			suppressed := true
			for j := 0; j < i; j++ {
				pch := intPic[j]
				if pch == 'Z' || pch == '9' {
					if outInt[j] != ' ' {
						suppressed = false
						break
					}
				}
			}
			if suppressed {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		}
	}

	if fracLen > 0 {
		return string(outInt) + "." + fracStr
	}
	return string(outInt)
}

func formatWithPic(val decimal.Decimal, pic string) string {
	if len(pic) > 0 && pic[0] == '-' {
		signChar := ' '
		if val.Sign() < 0 {
			signChar = '-'
		}
		abs := val.Abs()
		unsignedPic := pic[1:]
		unsignedFmt := formatUnsignedAbs(abs, unsignedPic)
		return string(signChar) + unsignedFmt
	}
	// unsigned
	abs := val.Abs()
	return formatUnsignedAbs(abs, pic)
}

func formatAmtEd(val decimal.Decimal) string {
	return formatWithPic(val, "ZZ,ZZ9.99")
}
func formatBalEd(val decimal.Decimal) string {
	return formatWithPic(val, "-Z,ZZZ,ZZ9.99")
}
func formatTotEd(val decimal.Decimal) string {
	return formatWithPic(val, "-ZZZ,ZZZ,ZZ9.99")
}

func truncateToField(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	// truncate fractional to scale (toward zero)
	// and integer part modulo 10^intDigits
	signNeg := v.Sign() < 0
	abs := v.Abs()
	intPart := abs.Truncate(0)
	frac := abs.Sub(intPart)

	// truncate frac to scale
	if scale > 0 {
		powScale := pow10Decimal(scale)
		frac = frac.Mul(powScale).Truncate(0).Div(powScale)
	} else {
		frac = decimal.NewFromInt(0)
	}
	var intMod decimal.Decimal
	if intDigits > 0 {
		intMod = intPart.Mod(pow10Decimal(intDigits))
	} else {
		intMod = decimal.NewFromInt(0)
	}
	newAbs := intMod.Add(frac)
	// ensure scale truncation
	newAbs = newAbs.Truncate(int32(scale))
	if signNeg && !newAbs.IsZero() {
		newAbs = newAbs.Neg()
	}
	return newAbs
}

func storeBal(v decimal.Decimal) decimal.Decimal {
	return truncateToField(v, 7, 2)
}
func storeBranchTot(v decimal.Decimal) decimal.Decimal {
	return truncateToField(v, 9, 2)
}
func storeGrandTot(v decimal.Decimal) decimal.Decimal {
	return truncateToField(v, 9, 2)
}

// file handling

func openLedgerFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file missing, treat as empty (EOF immediate)
		ledgerLines = []string{}
		ledgerIdx = 0
		return
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 1024*1024)
	scanner.Buffer(buf, 1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		// Scanner strips newline, keep as is
		ledgerLines = append(ledgerLines, line)
	}
	// ignore scanner error for now
	ledgerIdx = 0
}

func parseAmtField(s string) decimal.Decimal {
	// s length 7 digits
	trim := strings.TrimSpace(s)
	if trim == "" {
		return decimal.NewFromInt(0)
	}
	// keep only digits
	var digits strings.Builder
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits.WriteRune(ch)
		}
	}
	ds := digits.String()
	if ds == "" {
		return decimal.NewFromInt(0)
	}
	// ds may have up to 7 digits, but could be less if spaces
	// Parse as integer
	d, err := decimal.NewFromString(ds)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	// implied V99 => divide by 100
	return d.Shift(-2)
}

func READPARA() {
	if ledgerIdx >= len(ledgerLines) {
		WsEofFlag = "Y"
		return
	}
	line := ledgerLines[ledgerIdx]
	ledgerIdx++
	// pad with spaces to 14
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	ledgerRec.BrBranch = line[0:2]
	ledgerRec.BrAcct = line[2:6]
	ledgerRec.BrType = line[6:7]
	ledgerRec.BrAmt = parseAmtField(line[7:14])
}

func POSTPARA() {
	WsAmtEd = formatAmtEd(ledgerRec.BrAmt)
	switch ledgerRec.BrType {
	case "D":
		WsBal = storeBal(WsBal.Add(ledgerRec.BrAmt))
		display(ledgerRec.BrAcct, " D ", WsAmtEd)
	case "C":
		WsBal = storeBal(WsBal.Sub(ledgerRec.BrAmt))
		display(ledgerRec.BrAcct, " C ", WsAmtEd)
	default:
		WsSkipped = (WsSkipped + 1) % 100 // PIC 99 truncation
		display(ledgerRec.BrAcct, " ? SKIPPED")
	}
}

func ACCTBREAKPARA() {
	WsBalEd = formatBalEd(WsBal)
	display("  ACCOUNT ", WsPrevAcct, " BALANCE:", WsBalEd)
	WsBranchTot = storeBranchTot(WsBranchTot.Add(WsBal))
	WsBal = decimal.NewFromInt(0)
}

func BRANCHBREAKPARA() {
	WsTotEd = formatTotEd(WsBranchTot)
	display(" BRANCH ", WsPrevBranch, " TOTAL:", WsTotEd)
	WsGrandTot = storeGrandTot(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.NewFromInt(0)
}

func PROCESSPARA() {
	isFirst := WsFirstFlag == "Y"
	if isFirst {
		WsPrevBranch = ledgerRec.BrBranch
		WsPrevAcct = ledgerRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if ledgerRec.BrBranch != WsPrevBranch {
			ACCTBREAKPARA()
			BRANCHBREAKPARA()
			WsPrevBranch = ledgerRec.BrBranch
			WsPrevAcct = ledgerRec.BrAcct
		} else {
			if ledgerRec.BrAcct != WsPrevAcct {
				ACCTBREAKPARA()
				WsPrevAcct = ledgerRec.BrAcct
			}
		}
	}
	POSTPARA()
	READPARA()
}

func GRANDPARA() {
	WsTotEd = formatTotEd(WsGrandTot)
	display("GRAND TOTAL:", WsTotEd)
	// WS-SKIPPED is PIC 99 zero padded to 2 digits
	skippedStr := fmt.Sprintf("%02d", WsSkipped%100)
	display("SKIPPED: ", skippedStr)
}

func display(parts ...string) {
	s := strings.Join(parts, "")
	fmt.Println(s)
}

func main() {
	// init working storage
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevBranch = "  "
	WsPrevAcct = "    "
	WsBal = decimal.NewFromInt(0)
	WsBranchTot = decimal.NewFromInt(0)
	WsGrandTot = decimal.NewFromInt(0)
	WsSkipped = 0

	openLedgerFile()
	READPARA()
	for WsEofFlag != "Y" {
		PROCESSPARA()
	}
	if WsFirstFlag != "Y" {
		ACCTBREAKPARA()
		BRANCHBREAKPARA()
	}
	// CLOSE not needed
	GRANDPARA()
}
